-- Source: supabase/review-deletion.sql
-- Keep awarded points and ledger entries when a review is removed.
-- Match the columns, rather than assuming the deployed constraint name.
DO $$
DECLARE existing RECORD;
BEGIN
  FOR existing IN
    SELECT c.conname FROM pg_constraint c
    WHERE c.contype='f'
      AND c.conrelid='public.point_transactions'::regclass
      AND c.confrelid='public.reviews'::regclass
      AND c.conkey=ARRAY[(SELECT attnum FROM pg_attribute
        WHERE attrelid='public.point_transactions'::regclass AND attname='related_review_id')]::smallint[]
      AND c.confkey=ARRAY[(SELECT attnum FROM pg_attribute
        WHERE attrelid='public.reviews'::regclass AND attname='id')]::smallint[]
  LOOP
    EXECUTE format('ALTER TABLE public.point_transactions DROP CONSTRAINT %I',existing.conname);
  END LOOP;
  ALTER TABLE public.point_transactions
    ADD CONSTRAINT point_transactions_related_review_id_fkey
    FOREIGN KEY (related_review_id) REFERENCES public.reviews(id) ON DELETE SET NULL;
END $$;

COMMIT;
